const TOKEN = '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';
const REPO = 'Gaggs-daggs/vera-bot';
async function pushFile(path, b64) {
  const r = await fetch(`https://api.github.com/repos/${REPO}/contents/${path}`, {
    method: 'PUT',
    headers: { Authorization: `Bearer ${TOKEN}`, Accept: 'application/vnd.github+json', 'Content-Type': 'application/json' },
    body: JSON.stringify({ message: `Add ${path}`, content: b64, branch: 'main' })
  });
  const d = await r.json();
  if (r.ok) console.log('✅ ' + path);
  else console.log('❌ ' + path + ': ' + JSON.stringify(d));
}
(async () => {
  await pushFile("prompt_templates.py", "");
  await pushFile("bot.py", "");
  await pushFile("test_all.py", "");
  console.log('BATCH DONE');
})();